<script setup lang="ts">
definePageMeta({ middleware: ['auth', 'barber'], layout: 'dashboard' })
interface Media { id: string, url: string, type: 'image' | 'video' }
interface Work { id: string, title: string, description: string | null, media: Media[], reactions_count: number, comments_count: number, created_at: string }
interface PortfolioResponse { works: Work[], stats: Record<string, number> }
const { apiFetch } = useApi(); const { data, pending, error, refresh } = await useAsyncData<PortfolioResponse>('barber-portfolio', () => apiFetch('/barber/portfolio')); const works = computed(() => data.value?.works ?? []); const stats = computed(() => data.value?.stats ?? {})
const showForm = ref(false); const title = ref(''); const description = ref(''); const files = ref<File[]>([]); const saving = ref(false); const formError = ref('')
function selectFiles(event: Event) { files.value = Array.from((event.target as HTMLInputElement).files ?? []) }
async function publish() { saving.value = true; formError.value = ''; try { const body = new FormData(); body.append('title', title.value); if (description.value) body.append('description', description.value); files.value.forEach(file => body.append('media[]', file)); await apiFetch('/barber/works', { method: 'POST', body }); showForm.value = false; title.value = ''; description.value = ''; files.value = []; await refresh() } catch (err: unknown) { formError.value = (err as { data?: { message?: string } })?.data?.message ?? 'No se pudo publicar.' } finally { saving.value = false } }
async function remove(work: Work) { if (!confirm(`Eliminar ${work.title}?`)) return; await apiFetch(`/barber/works/${work.id}`, { method: 'DELETE' }); await refresh() }
</script>
<template><div class="p-4 sm:p-6 lg:p-8"><header class="mb-6 flex items-end justify-between"><div><p class="text-xs uppercase tracking-widest text-muted">Mi espacio</p><h1 class="mt-1 text-2xl font-semibold text-ink">Mi <span class="text-gold">Portafolio</span></h1><p class="mt-1 text-sm text-muted">Tu carta de presentacion profesional.</p></div><button class="rounded-lg bg-gold px-4 py-2 text-sm font-bold text-black" @click="showForm = true">+ Publicar trabajo</button></header><section class="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="card in [{k:'total_works',l:'Trabajos'},{k:'total_reactions',l:'Reacciones'},{k:'total_comments',l:'Comentarios'},{k:'total_saves',l:'Guardados'}]" :key="card.k" class="ui-card p-4"><p class="text-xs uppercase text-muted">{{ card.l }}</p><p class="mt-2 text-2xl font-black text-ink">{{ stats[card.k] ?? 0 }}</p></div></section><p v-if="pending" class="text-muted">Cargando...</p><p v-else-if="error" class="text-red-400">No se pudo cargar el portafolio.</p><section v-else class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><article v-for="work in works" :key="work.id" class="ui-card overflow-hidden"><div class="aspect-video bg-main"><video v-if="work.media[0]?.type === 'video'" :src="work.media[0].url" controls class="h-full w-full object-cover"/><img v-else-if="work.media[0]" :src="work.media[0].url" :alt="work.title" class="h-full w-full object-cover"><div v-else class="flex h-full items-center justify-center text-muted">Sin medio</div></div><div class="p-4"><div class="flex items-start justify-between gap-3"><div><h2 class="font-bold text-ink">{{ work.title }}</h2><p class="mt-1 text-sm text-muted">{{ work.description }}</p></div><button class="text-xs text-red-400" @click="remove(work)">Eliminar</button></div><p class="mt-3 text-xs text-muted">{{ work.reactions_count }} reacciones · {{ work.comments_count }} comentarios · {{ work.media.length }} archivos</p></div></article><div v-if="!works.length" class="ui-card col-span-full py-16 text-center text-sm text-muted">Aun no has publicado trabajos.</div></section><div v-if="showForm" class="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4" @click.self="showForm = false"><form class="w-full max-w-lg space-y-4 rounded-2xl border border-line bg-card p-6" @submit.prevent="publish"><h2 class="text-lg font-bold text-ink">Publicar trabajo</h2><input v-model="title" required maxlength="255" placeholder="Titulo" class="w-full rounded-lg border border-line bg-main px-3 py-2 text-ink"><textarea v-model="description" maxlength="2000" rows="3" placeholder="Descripcion" class="w-full rounded-lg border border-line bg-main px-3 py-2 text-ink"/><input type="file" required multiple accept="image/*,video/*" class="w-full text-sm text-muted" @change="selectFiles"><p class="text-xs text-muted">Hasta 10 imagenes o videos. Maximo 50 MB por archivo.</p><p v-if="formError" class="text-sm text-red-400">{{ formError }}</p><div class="flex gap-3"><button :disabled="saving || !files.length" class="flex-1 rounded-lg bg-gold px-4 py-2 font-bold text-black disabled:opacity-50">{{ saving ? 'Publicando...' : 'Publicar' }}</button><button type="button" class="rounded-lg border border-line px-4 py-2 text-muted" @click="showForm = false">Cancelar</button></div></form></div></div></template>
